#!/usr/bin/env node
/**
 * Detect-and-notify check for the CIRCL interop cross-check vectors under
 * packages/core/src/vectors/interop/.
 *
 * Reports whether a newer github.com/cloudflare/circl release is published
 * than the version recorded in the vectors' own `meta.counterpartVersion` —
 * the CIRCL version those files were actually cross-checked against when
 * generated by scripts/interop/generate-circl-vectors.mts. A newer CIRCL
 * release is what could change what the vectors should say; it does not by
 * itself mean anything is wrong.
 *
 * This script only reads the Go module proxy (plain HTTPS — no `go` binary,
 * same "no Go in CI" rule the generator itself follows) and the repo. It
 * never regenerates the vectors, never touches any file under
 * packages/core/src/vectors/interop/, and never opens a PR. Regenerating
 * requires Go, the CIRCL helper, and a human reading the cross-check
 * results — see scripts/interop/generate-circl-vectors.mts. A mismatch
 * found after regenerating is a finding to investigate, not a test to fix.
 *
 * Writes `has-drift` (and, on drift, `issue-title`) to $GITHUB_OUTPUT when
 * run in Actions, and the issue body to the file path given by --report
 * (default: circl-drift-report.md in the current directory).
 *
 * Usage: node scripts/check-circl-drift.mjs [--report <path>]
 *
 * `evaluateDrift` and friends below are exported so __tests__/ can exercise
 * the real logic against fixture vector files with the network call
 * (`fetchLatestVersion`) stubbed out — see
 * scripts/__tests__/check-circl-drift.test.mjs.
 */
import console from 'node:console';
import { appendFileSync, readFileSync, writeFileSync } from 'node:fs';
import { get as httpsGet } from 'node:https';
import { dirname, join } from 'node:path';
import process from 'node:process';
import { fileURLToPath } from 'node:url';

export const COUNTERPART = 'github.com/cloudflare/circl';

const SCRIPT_DIR = dirname(fileURLToPath(import.meta.url));
const DEFAULT_VECTORS_DIR = join(SCRIPT_DIR, '../src/vectors/interop');
const GENERATOR_REL = 'packages/core/scripts/interop/generate-circl-vectors.mts';

/** The three interop vector files, each carrying its own `meta.counterpartVersion`. */
export const VECTOR_FILE_NAMES = ['circl-mldsa.json', 'circl-xwing.json', 'circl-mlkem768.json'];

/**
 * Real (network-hitting) fetcher — a plain HTTPS GET against the Go module
 * proxy, no `go` binary involved. Swapped out for a stub in tests.
 */
export function fetchLatestVersionFromProxy(modulePath = COUNTERPART) {
  return new Promise((resolve, reject) => {
    const req = httpsGet(`https://proxy.golang.org/${modulePath}/@latest`, (res) => {
      const status = res.statusCode ?? 0;
      if (status < 200 || status >= 300) {
        res.resume();
        reject(new Error(`Go module proxy returned ${status} for ${modulePath}`));
        return;
      }
      let data = '';
      res.setEncoding('utf8');
      res.on('data', (chunk) => {
        data += chunk;
      });
      res.on('end', () => {
        try {
          resolve(JSON.parse(data).Version);
        } catch (error) {
          reject(error);
        }
      });
    });
    req.on('error', reject);
  });
}

function readVectorMeta(vectorsDir, fileName) {
  const doc = JSON.parse(readFileSync(join(vectorsDir, fileName), 'utf8'));
  return doc.meta;
}

/**
 * Core check. Reads each vector file's recorded `meta` from `vectorsDir`;
 * the network call goes through `fetchLatestVersion`, overridable.
 */
export async function evaluateDrift({
  vectorsDir = DEFAULT_VECTORS_DIR,
  fetchLatestVersion = fetchLatestVersionFromProxy,
  repo = process.env.GITHUB_REPOSITORY ?? 'jeloercc/pqc-sdk',
} = {}) {
  const metas = VECTOR_FILE_NAMES.map((name) => ({ name, meta: readVectorMeta(vectorsDir, name) }));

  const recordedVersions = [...new Set(metas.map(({ meta }) => meta.counterpartVersion))];
  const inconsistent = recordedVersions.length > 1;
  const recorded = recordedVersions[0];

  const latest = await fetchLatestVersion(COUNTERPART);
  const versionDrift = latest !== recorded;
  const hasDrift = versionDrift || inconsistent;

  const regenerateCommand = metas[0].meta.regenerateCommand;
  const issueTitle = `Interop-vector drift: ${COUNTERPART}`;
  const reportBody = buildReportBody({
    recorded,
    latest,
    versionDrift,
    inconsistent,
    metas,
    regenerateCommand,
    repo,
  });

  return { recorded, latest, versionDrift, inconsistent, hasDrift, issueTitle, reportBody };
}

export function buildReportBody({
  recorded,
  latest,
  versionDrift,
  inconsistent,
  metas,
  regenerateCommand,
  repo,
}) {
  const lines = [];
  lines.push(`Automated interop-vector drift check for \`${COUNTERPART}\` (CIRCL).`);
  lines.push('');

  if (inconsistent) {
    lines.push(
      '**The three vector files disagree on which CIRCL version they were generated ' +
        'against.** That needs a look on its own, independent of whether a newer release ' +
        'exists:',
    );
    lines.push('');
    for (const { name, meta } of metas) {
      lines.push(`- \`${name}\`: \`${meta.counterpartVersion}\``);
    }
    lines.push('');
  }

  if (versionDrift) {
    lines.push(
      `**A newer CIRCL release is published.** Vectors recorded: \`${recorded}\`. ` +
        `Latest: \`${latest}\`.`,
    );
  } else {
    lines.push(
      `**No newer CIRCL release.** \`${recorded}\` is still the latest published version.`,
    );
  }
  lines.push('');

  lines.push(
    'Affected vector files (all under `packages/core/src/vectors/interop/`): ' +
      VECTOR_FILE_NAMES.map((f) => `\`${f}\``).join(', ') +
      '.',
  );
  lines.push('');
  lines.push('To regenerate and re-run the cross-check:');
  lines.push('');
  lines.push('```');
  lines.push(regenerateCommand);
  lines.push('```');
  lines.push('');
  lines.push(
    '**A mismatch after regenerating is a finding to investigate, not a test to fix.** ' +
      'That is exactly the outcome this interop check exists to catch — see ' +
      `[\`${GENERATOR_REL}\`](https://github.com/${repo}/blob/main/${GENERATOR_REL}) ` +
      'for what it asserts and why it stops and writes nothing rather than adjusting ' +
      'anything on a mismatch.',
  );
  lines.push('');
  lines.push(
    'This check is detect-and-notify only — it never regenerates the vectors, never ' +
      'touches any file under `packages/core/src/vectors/interop/`, and never opens a PR.',
  );
  return lines.join('\n') + '\n';
}

async function main() {
  const reportArgIdx = process.argv.indexOf('--report');
  const reportPath =
    reportArgIdx !== -1
      ? process.argv[reportArgIdx + 1]
      : join(process.cwd(), 'circl-drift-report.md');

  const result = await evaluateDrift();

  writeFileSync(reportPath, result.reportBody);

  if (process.env.GITHUB_OUTPUT) {
    appendFileSync(process.env.GITHUB_OUTPUT, `has-drift=${result.hasDrift}\n`);
    appendFileSync(process.env.GITHUB_OUTPUT, `issue-title=${result.issueTitle}\n`);
  }

  console.log(result.reportBody);
  console.log(`has-drift=${result.hasDrift}`);
}

// Only run as the CLI entry point — not when __tests__/ imports this module.
if (import.meta.url === `file://${process.argv[1]}`) {
  await main();
}
